using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using SmartIT.Infrastructure;
namespace SmartIT.Web.Controllers;
public record LoginViewModel(string Email,string Password,bool RememberMe=false);
public class AccountController(SignInManager<ApplicationUser> signIn):Controller { [AllowAnonymous] public IActionResult Login(string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;return View(new LoginViewModel("",""));} [HttpPost][AllowAnonymous][ValidateAntiForgeryToken] public async Task<IActionResult> Login(LoginViewModel model,string? returnUrl=null){if(!ModelState.IsValid())return View(model);var result=await signIn.PasswordSignInAsync(model.Email,model.Password,model.RememberMe,false);if(result.Succeeded)return LocalRedirect(returnUrl??"/");ModelState.AddModelError("","Invalid credentials.");return View(model);}[HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> Logout(){await signIn.SignOutAsync();return RedirectToAction(nameof(Login));} }
